arguments.command:
python3 - <<'EOF'
p='src/run.test.ts'
s=open(p).read()
anchor='''	it("pr_number reviews join that PR's thread and can post to it", async () => {'''
new='''	it("expands a prompt template in a direct prompt", async () => {
		const w = world();
		let seen: string[] = [];
		w.faux.setResponses([
			(context) => {
				seen = userTexts(context.messages);
				return fauxAssistantMessage("Notes.");
			},
		]);
		const deps = w.deps(
			undefined,
			{ outputMode: "output", prompt: "/notes v2", agentDir: ".agent" },
			{},
		);
		write(join(deps.cwd, ".agent/prompts/notes.md"), "Write notes for $1.");

		await run(deps);

		expect(seen[0]).toContain("## Task\\nWrite notes for v2.\\n");
	});

'''
assert anchor in s
s=s.replace(anchor,new+anchor,1)
open(p,'w').write(s)
EOF
npx oxfmt >/dev/null; npx vitest run src/run.test.ts -t "direct prompt" 2>&1 | grep -E "✓|×|Tests"
